package blockbranch.realistic;
import java.nio.file.*;import java.util.*;import net.minecraft.core.BlockPos;
/** Inspect only the already-surveyed six component budgets; do not expand the proposal stream. */
public final class ReimaginedMonumentDiagnosis {
 public static void register(){net.fabricmc.fabric.api.event.lifecycle.v1.ServerLifecycleEvents.SERVER_STARTED.register(server->{try{var l=server.overworld();var g=(RealisticGenerator)l.getChunkSource().getGenerator();var random=l.getChunkSource().randomState();var sites=g.reimaginedDefinition()>0?g.reimagined(random):new ReimaginedSites().bind(l.getSeed(),g,random);var d=g.hutPlanningTerrain(random).drainage();var selected=ReimaginedSites.Region.class.getDeclaredField("selected");selected.setAccessible(true);var proposal=ReimaginedSites.class.getDeclaredMethod("proposal",int.class,int.class);proposal.setAccessible(true);var biome=ReimaginedSites.class.getDeclaredMethod("biome",int.class,int.class,int.class);biome.setAccessible(true);var rows=new ArrayList<Object>();for(var region:sites.ordered(5,BlockPos.ZERO,6000000)){int biomes=0,water=0,passed=0;var candidates=new ArrayList<int[]>();for(int cell:(int[])selected.get(region))for(int n=0;n<64;n++){long q=(long)proposal.invoke(sites,cell,n);int x=(int)(q>>32),z=(int)q;if(!(boolean)biome.invoke(sites,5,x,z)){biomes++;continue;}int min=Integer.MAX_VALUE,max=Integer.MIN_VALUE;boolean wet=true;for(int dz=-48;dz<=48;dz+=24)for(int dx=-48;dx<=48;dx+=24){var s=d.sample(x+dx,z+dz);min=Math.min(min,s.height());max=Math.max(max,s.height());wet&=d.oceanWater(x+dx,z+dz,s)&&s.height()<=20;}if(!wet){water++;continue;}candidates.add(new int[]{x,z,min,max,max-min});if(max-min<=12)passed++;}candidates.sort(Comparator.comparingInt(v->v[4]));var best=new ArrayList<Object>();for(var p:candidates.stream().limit(3).toList()){int min=Integer.MAX_VALUE,max=Integer.MIN_VALUE;boolean wet=true;for(int dz=-48;dz<=48;dz++)for(int dx=-48;dx<=48;dx++){var s=d.sample(p[0]+dx,p[1]+dz);min=Math.min(min,s.height());max=Math.max(max,s.height());wet&=d.oceanWater(p[0]+dx,p[1]+dz,s);}best.add(Map.of("x",p[0],"z",p[1],"gridRelief",p[4],"fullMin",min,"fullMax",max,"fullRelief",max-min,"fullOcean",wet));}rows.add(Map.of("owner",region.owner(),"nativeBiomeRejected",biomes,"coarseWaterRejected",water,"coarseRelief12Passed",passed,"bestExistingProposals",best));}Files.writeString(Path.of("monument-diagnosis.json"),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(rows));Files.writeString(Path.of("monument-diagnosis-result.txt"),"PASS");}catch(Throwable t){blockbranch.Blockbranch.LOGGER.error("MONUMENT_DIAGNOSIS_FAIL",t);try{Files.writeString(Path.of("monument-diagnosis-result.txt"),"FAIL "+t);}catch(Exception ignored){}}finally{server.halt(false);}});}
}
